#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_key: host-task-nature-confirm
 * rule_id: b758b559-ba03-4586-9f9f-7f887cee80a6
 * statement: 执行前必须确认任务是否需要改动代码。如果是计划或技术文档任务，不得修改源代码。避免过度工程化，只做直接请求或必要的更改。
 * trae_event: UserPromptSubmit
 * matcher: (空，UserPromptSubmit 不支持 matcher)
 *
 * 场景发散设计结论：
 *
 * 1. 解构触发条件：
 *    - "计划任务"包含：制定方案、设计方案、规划、roadmap、架构设计、评审、分析、调研、讨论
 *    - "技术文档任务"包含：写文档、README、设计文档、API 文档、使用说明、注释、规格说明
 *    - "改动代码"包含：Edit/Write 工具操作源代码文件（.py/.ts/.js/.go/.java 等）
 *
 * 2. 场景分级：
 *    - critical（必须拦截）：prompt 明确要求计划/文档/讨论 + 不含任何代码改动关键词
 *    - lightweight（提醒但不拦截）：prompt 含计划关键词 + 也含代码改动关键词（可能是需要边计划边写）
 *    - skip（不触发）：prompt 明确要求改动代码；prompt 是纯问答；prompt 含"实施/执行/落地"等执行类关键词
 *
 * 3. 边界情况：
 *    - prompt 模糊（既含计划又含代码关键词）→ lightweight（只提醒，不拦截）
 *    - prompt 是纯问答（"什么是..."）→ skip
 *    - 用户明确说"先计划再实施" → skip（用户已意识到需要分阶段）
 *
 * 4. shouldRun 设计：
 *    - 检查 prompt 是否含 PLAN_KEYWORDS（计划/方案/设计/文档/讨论/评审）
 *    - 检查 prompt 是否不含 CODE_KEYWORDS（改/写/实现/修复/添加/删除代码）
 *    - 如果同时含两类关键词，返回 false（不拦截，只提醒）
 *
 * 5. run 检查逻辑：
 *    - 如果是纯计划/文档任务，REJECT 并提示不得修改源代码
 *    - 提供检查命令帮助用户确认任务性质
 */

import { runHook, getCwd } from "./_lib.mjs";

// 计划/文档关键词
const PLAN_KEYWORDS = [
  "计划", "plan", "方案", "design", "规划", "roadmap", "设计", "文档",
  "README", "readme", "规格", "spec", "分析", "analysis", "调研",
  "讨论", "discuss", "评审", "review", "整理", "梳理", "思路",
  "建议", "suggestion", "对比", "compare", "选型", "选什么", "怎么做"
];

// 代码改动关键词
const CODE_KEYWORDS = [
  "改", "modify", "写", "write", "实现", "implement", "修复", "fix",
  "添加", "add", "删除", "delete", "重构", "refactor", "优化", "optimize",
  "创建", "create", "更新", "update", "编辑", "edit", "代码", "code",
  "函数", "function", "类", "class", "模块", "module", "文件", "file",
  "落地", "实施", "执行", "execute"
];

// 纯问答关键词（不需要改动代码）
const QA_KEYWORDS = [
  "什么是", "what is", "为什么", "why", "如何", "how to",
  "解释", "explain", "说明", "describe", "帮我", "help",
  "看看", "检查", "check"
];

// 判断是否应该触发
function shouldRun(context) {
  const prompt = (context.userPrompt ?? "").toLowerCase();

  // 1. 如果是纯问答，不触发
  if (QA_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()))) {
    // 但如果同时含代码关键词，可能需要改动代码来演示，不拦截
    if (!CODE_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()))) {
      return false;
    }
  }

  // 2. 如果含执行/落地关键词，不触发（用户明确要实施）
  if (CODE_KEYWORDS.filter(kw => ["落地", "实施", "执行", "execute"].includes(kw)).some(kw => prompt.includes(kw.toLowerCase()))) {
    return false;
  }

  // 3. 检查是否含计划关键词
  const hasPlanKeyword = PLAN_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()));

  // 4. 检查是否含代码改动关键词
  const hasCodeKeyword = CODE_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()));

  // 5. 如果同时含两类关键词，不拦截（可能是边计划边实施）
  if (hasPlanKeyword && hasCodeKeyword) {
    return false;
  }

  // 6. 如果只含计划关键词，不含代码关键词，触发拦截
  if (hasPlanKeyword && !hasCodeKeyword) {
    return true;
  }

  return false;
}

// 执行检查
function run(context) {
  const prompt = context.userPrompt ?? "";

  return {
    action: "REJECT",
    reason: `任务性质确认：当前 prompt 含计划/文档关键词但不含代码改动关键词。根据"任务性质确认规则"，计划或技术文档任务不得修改源代码。`,
    suggestions: [
      "确认任务性质：",
      "  - 如果只需要方案/文档，明确说'只做文档/方案，不改动代码'",
      "  - 如果需要实施方案，补充'然后实施/落地'",
      "避免过度工程化：只做直接请求或必要的更改",
      "检查命令：grep -E '(plan|design|方案|文档)' <your-prompt>"
    ]
  };
}

// 主流程入口
runHook(shouldRun, run, "UserPromptSubmit");